inline BasicObject* Array::m_size(Array* args, Hash* kwargs, Proc* block) {
  return new Integer(static_cast<int64_t>(data.size()));
}

inline BasicObject* Array::m_length(Array* args, Hash* kwargs, Proc* block) {
  return new Integer(static_cast<int64_t>(data.size()));
}

inline BasicObject* Array::m_empty_q(Array* args, Hash* kwargs, Proc* block) {
  return boxed_bool(data.empty());
}

inline BasicObject* Array::m_first(Array* args, Hash* kwargs, Proc* block) {
  return data.empty() ? nil_instance() : data.front();
}

inline BasicObject* Array::m_last(Array* args, Hash* kwargs, Proc* block) {
  return data.empty() ? nil_instance() : data.back();
}

inline BasicObject* Array::m_aref(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* idx = array_at(args, 0);
  int64_t i = static_cast<Integer*>(idx)->raw_;
  if (i < 0) i += static_cast<int64_t>(data.size());
  if (i < 0 || i >= static_cast<int64_t>(data.size())) return nil_instance();
  return data[i];
}

inline BasicObject* Array::m_aset(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* idx = array_at(args, 0);
  BasicObject* val = array_at(args, 1);
  int64_t i = static_cast<Integer*>(idx)->raw_;
  if (i < 0) i += static_cast<int64_t>(data.size());
  if (i >= static_cast<int64_t>(data.size())) data.resize(i + 1, nil_instance());
  data[i] = val;
  return val;
}

inline BasicObject* Array::m_push(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* val = array_at(args, 0);
  data.push_back(val); return this;
}

inline BasicObject* Array::m_lshift(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* val = array_at(args, 0);
  data.push_back(val); return this;
}

inline BasicObject* Array::m_clear(Array* args, Hash* kwargs, Proc* block) {
  data.clear(); return this;
}

inline BasicObject* Array::m_pop(Array* args, Hash* kwargs, Proc* block) {
  if (data.empty()) return nil_instance(); BasicObject* v = data.back(); data.pop_back(); return v;
}

inline BasicObject* Array::m_shift(Array* args, Hash* kwargs, Proc* block) {
  if (data.empty()) return nil_instance(); BasicObject* v = data.front(); data.erase(data.begin()); return v;
}

inline BasicObject* Array::m_unshift(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* v = array_at(args, 0);
  data.insert(data.begin(), v); return this;
}

inline BasicObject* Array::m_replace(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* other = array_at(args, 0);
  auto* o = static_cast<Array*>(other); data = o->data; return this;
}

inline BasicObject* Array::m_dup(Array* args, Hash* kwargs, Proc* block) {
  Array* r = new Array(); r->data = data; return r;
}

inline BasicObject* Array::m_concat(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* other = array_at(args, 0);
  auto* o = static_cast<Array*>(other); data.insert(data.end(), o->data.begin(), o->data.end()); return this;
}

inline BasicObject* Array::m_initialize(Array* args, Hash* kwargs, Proc* block) {
  if (args->data.empty()) return this;
  int64_t n = static_cast<Integer*>(args->data[0])->raw_;
  BasicObject* fill = args->data.size() >= 2 ? args->data[1] : nil_instance();
  data.assign(n, fill);
  return this;
}

