inline BasicObject* Binding::m_clone(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* freeze = (kwargs ? [&]() -> BasicObject* { auto _it = kwargs->data.find(intern("freeze")); return _it == kwargs->data.end() ? (nil_instance()) : _it->second; }() : (nil_instance()));
  Proc* _block = block;
  BasicObject* c = nil_instance();
  c = this->m_dup((new Array({})), nullptr, nullptr);
  if (truthy(freeze->m_nil_q((new Array({})), nullptr, nullptr))) {
    if (truthy(this->m_frozen_q((new Array({})), nullptr, nullptr))) {
      c->m_freeze((new Array({})), nullptr, nullptr);
    }
  } else {
    if (truthy(freeze)) {
      c->m_freeze((new Array({})), nullptr, nullptr);
    }
  }
  return c;
  return nil_instance();
}

