inline BasicObject* Parser_Rewriter::m_process(Array* args, Hash* kwargs, Proc* block) {
  BasicObject* node = array_at(args, 0);
  Proc* _block = block;
  BasicObject* on_handler = nil_instance();
  BasicObject* new_node = nil_instance();
  if (truthy(node->m_nil_q((new Array({})), nullptr, nullptr))) {
    /* skipped: from_expr: nil node — caller passed missing AST */
  }
  node = node->m_to_ast((new Array({})), nullptr, nullptr);
  on_handler = ((new String("", 0))->m_plus((new Array({(new String("on_", 3))})), nullptr, nullptr)->m_plus((new Array({(node->m_type((new Array({})), nullptr, nullptr))->m_to_s((new Array({})), nullptr, nullptr)})), nullptr, nullptr))->m_to_sym((new Array({})), nullptr, nullptr);
  if (truthy(this->m_respond_to_q((new Array({on_handler})), nullptr, nullptr))) {
    new_node = this->m_send((new Array({on_handler, node})), nullptr, nullptr);
  } else {
    new_node = this->m_handler_missing((new Array({node})), nullptr, nullptr);
  }
  if (truthy(new_node)) {
    node = new_node;
  }
  return node;
  return nil_instance();
}

